"use strict";(()=>{const input=document.getElementById('term-search');if(!input)return;const terms=[...document.querySelectorAll('.term')],count=document.getElementById('term-count'),empty=document.getElementById('empty-result');input.addEventListener('input',()=>{const q=input.value.trim().toLocaleLowerCase();let n=0;terms.forEach(t=>{t.hidden=!t.textContent.toLocaleLowerCase().includes(q);if(!t.hidden)n++});count.textContent=(q?'符合搜尋：':'全部 ')+n+' 個詞條';empty.hidden=n!==0;});})();
